#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/byteorder.h>

#include "bq27z746.h"

LOG_MODULE_REGISTER(EMUL_BQ27Z746, LOG_LEVEL_INF);

#define BQ27Z746_EMUL_MAX_REG 0x3D /* Max register address seen in logs + 1 */

struct bq27z746_emul_data {
	struct i2c_emul_data i2c_emul;
	uint16_t regs[BQ27Z746_EMUL_MAX_REG];
};

static int bq27z746_emul_read_word(const struct emul *target, int reg_addr, uint16_t *val)
{
	struct bq27z746_emul_data *data = (struct bq27z746_emul_data *)target->data;

	if (reg_addr >= BQ27Z746_EMUL_MAX_REG) {
		LOG_ERR("Invalid register address 0x%x", reg_addr);
		return -EIO;
	}

	*val = data->regs[reg_addr];
	LOG_INF("read 0x%x = 0x%x", reg_addr, *val);
	return 0;
}

static int bq27z746_emul_write_word(const struct emul *target, int reg_addr, uint16_t val)
{
	struct bq27z746_emul_data *data = (struct bq27z746_emul_data *)target->data;

	if (reg_addr >= BQ27Z746_EMUL_MAX_REG) {
		LOG_ERR("Invalid register address 0x%x", reg_addr);
		return -EIO;
	}

	data->regs[reg_addr] = val;
	LOG_INF("write 0x%x = 0x%x", reg_addr, val);
	return 0;
}

static int bq27z746_emul_transfer(const struct emul *target, struct i2c_msg *msgs, int num_msgs,
				  int addr)
{
	struct bq27z746_emul_data *data = (struct bq27z746_emul_data *)target->data;
	int ret;

	if (num_msgs < 1) {
		return 0;
	}

	/* Write register address */
	if (!(msgs[0].flags & I2C_MSG_RW_BIT) && msgs[0].len == 1) {
		data->i2c_emul.next_reg_addr = msgs[0].buf[0];
		msgs++;
		num_msgs--;
	}

	for (int i = 0; i < num_msgs; i++) {
		if (msgs[i].flags & I2C_MSG_RW_BIT) { /* Read */
			if (msgs[i].len == 2) { /* Read word */
				uint16_t val;

				ret = bq27z746_emul_read_word(target, data->i2c_emul.next_reg_addr, &val);
				if (ret < 0) {
					return ret;
				}
				sys_put_le16(val, msgs[i].buf);
			} else {
				LOG_ERR("Unsupported read length %d", msgs[i].len);
				return -EIO;
			}
		} else { /* Write */
			if (msgs[i].len == 2) { /* Write word */
				uint16_t val = sys_get_le16(msgs[i].buf);

				ret = bq27z746_emul_write_word(target, data->i2c_emul.next_reg_addr, val);
				if (ret < 0) {
					return ret;
				}
			} else {
				LOG_ERR("Unsupported write length %d", msgs[i].len);
				return -EIO;
			}
		}
		data->i2c_emul.next_reg_addr++;
	}

	return 0;
}

